//! 🔤️ Native optional text plans preserve exact owners and allocation-free alias retirement.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneBorrowAuthority;
fn close<T:Puzzle2dTextIntent>(cursor:&mut Puzzle2dTextPreparationCursor<T>){
 cursor.begin_close();for _ in 0..64{if cursor.terminal_is_empty(){return}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(1,17));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!heap.overflowed);assert!(!matches!(step.unwrap(),SnapshotRetirementStep::Pending{released_items,released_bytes}if released_items>1||released_bytes!=0))}panic!("text aliases did not close")
}
fn law<T:Puzzle2dTextIntent+Clone>(snapshot:&Puzzle2dSnapshot,payload:T,target:bool,expected:&str){
 assert!(std::mem::size_of::<Puzzle2dTextPreparationCursor<T>>()<=4096);let original=serde_json::to_value(snapshot).unwrap();let source=RetainedCloneBorrowAuthority::new("original optional text snapshot");let mutation=RetainedCloneBorrowAuthority::new("original optional text intent");let grant=BoundedOrdGrant{maximum_items:1,maximum_bytes:17};
 let(mut cursor,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(Puzzle2dTextPreparationCursor::<T>::default);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),BoundedOrdGrant{maximum_items:0,maximum_bytes:0}));assert_eq!(step.unwrap(),Puzzle2dTextPreparationStep::Pending(Default::default()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 let mut plan=None;for _ in 0..100000{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!heap.overflowed);let step=step.unwrap();let progress=match step{Puzzle2dTextPreparationStep::Pending(progress)|Puzzle2dTextPreparationStep::Complete{progress,..}=>progress};assert!(progress.fits(grant));if let Puzzle2dTextPreparationStep::Complete{plan:value,..}=step{plan=Some(value);break}}
 let plan=plan.expect("native optional text plan did not finish");assert_eq!(plan.index,if target{Some(0)}else{None});assert_eq!(match plan.disposition{Puzzle2dTextDisposition::Changed=>"changed",Puzzle2dTextDisposition::NoOp=>"noOp",Puzzle2dTextDisposition::TargetMissing=>"targetMissing"},expected);assert!(cursor.lookup.terminal_is_empty()&&cursor.comparison.terminal_is_empty());assert_eq!(cursor.take(),Some(plan));assert_eq!(cursor.take(),None);close(&mut cursor);
 for pause in [0,1,3,7,17]{let mut cursor=Puzzle2dTextPreparationCursor::<T>::default();for _ in 0..pause{if matches!(cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),grant).unwrap(),Puzzle2dTextPreparationStep::Complete{..}){break}}close(&mut cursor);assert_eq!(cursor.take(),None)}
 let mut cursor=Puzzle2dTextPreparationCursor::<T>::default();cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),grant).unwrap();let swapped=payload.clone();assert!(cursor.advance(source.borrow(snapshot),mutation.borrow(&swapped),grant).is_err());close(&mut cursor);assert_eq!(serde_json::to_value(snapshot).unwrap(),original);
}
#[test]
fn history_edit_puzzle2d_borrowed_optional_text_preparation_matches_original_paged_chunks_and_alias_cancel(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for row in corpus["cases"].as_array().unwrap(){let mut snapshot=Puzzle2dSnapshot::default();let previous=row["before"].as_str().map(PagedUtf8::from);let next=row["next"].as_str().map(PagedUtf8::from);let target=row["target"].as_bool().unwrap();let id=if target{"retained"}else{"missing"}.into();let expected=row["expected"].as_str().unwrap();if row["role"]=="nodeIcon"{snapshot.nodes.push(crate::Puzzle2dNode{id:"retained".into(),icon_kind:previous,..Default::default()});snapshot.nodes.push(crate::Puzzle2dNode{id:"retained".into(),icon_kind:Some("second owner".into()),..Default::default()});law(&snapshot,ChangeNodeIcon{id,new_icon_kind:next},target,expected)}else{snapshot.target_regions.push(crate::Puzzle2dTargetRegion{id:"retained".into(),label:previous,..Default::default()});snapshot.target_regions.push(crate::Puzzle2dTargetRegion{id:"retained".into(),label:Some("second owner".into()),..Default::default()});law(&snapshot,EditTargetRegionLabel{id,new_label:next},target,expected)}}
 let text="😀\0甲".repeat(20000);let mut snapshot=Puzzle2dSnapshot::default();snapshot.nodes.push(crate::Puzzle2dNode{id:"retained".into(),icon_kind:Some(text.clone().into()),..Default::default()});law(&snapshot,ChangeNodeIcon{id:"retained".into(),new_icon_kind:Some(text.into())},true,"noOp");
 eprintln!("[DEBUG] optional icon and region label preserve fourteen native first-owner cases plus160000byte Unicode/NUL equality, zeroheap constructor/advance, source fence and five exact alias cancellation points");
}
